#!/usr/bin/env bash
# P0 fixes round 3:
#   1) Student-t quantile in the LCB (correct small-n penalty)
#   2) --pool-calib : leakage-free cross-seed warm-up pooling for avg@k
#      benchmarks (AIME: 12 -> ~96 paired calibration instances)
#   3) scripts/ntc_slo_report.py : the SLO-attainment table for the paper
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing P0 fixes round 3..."
decode "apply_pooled_t.py" << 'B64EOF'

B64EOF
decode "scripts/ntc_slo_report.py" << 'B64EOF'

B64EOF
python apply_pooled_t.py && rm apply_pooled_t.py
echo ""
echo "Installed. Re-run AIME with --pool-calib, then the SLO report."